// Native browser geometry for synthetic light-task fragment generated by light-task.mjs.
import assert from 'node:assert/strict';
import {spawnSync} from 'node:child_process';
import {existsSync,mkdtempSync,readFileSync,writeFileSync,rmSync} from 'node:fs';
import {tmpdir} from 'node:os';
import {join} from 'node:path';
import {pathToFileURL} from 'node:url';
import { findBrowser } from "../helpers/browser.mjs";
import { writePage } from "../helpers/page.mjs";
const browser = findBrowser();
if(!browser){if(process.env.LUBI_REQUIRE_BROWSER==='1')throw Error('Native browser required');console.log('SKIP light task layout');process.exit(0)}
const fragment=readFileSync(new URL('../../preview/light-task-fragment.html',import.meta.url),'utf8');
const styles=readFileSync(new URL('../../styles.css',import.meta.url),'utf8');
const tmp=mkdtempSync(join(tmpdir(),'lubi-light-'));
try{
 for(const theme of ['light','dark']) for(const [w,h] of [[900,800],[390,844],[320,700]]){
  const shim=`:root{--background-primary:${theme==='dark'?'#111':'#fff'};--background-modifier-border:#888;--text-normal:${theme==='dark'?'#eee':'#111'};--text-muted:#888;--interactive-accent:#333;--text-on-accent:#fff}html,body{margin:0;font:14px sans-serif;background:var(--background-primary);color:var(--text-normal)}*{box-sizing:border-box}.modal{padding:16px;margin:10px auto}.modal-content{min-width:0}input,select,textarea,button{font:inherit;color:inherit;background:var(--background-primary);border:1px solid #888}button{border-radius:5px}h2,.modal-title{font-size:20px}`;
  const probe=`<script>addEventListener('load',()=>{const m=document.querySelector('.modal'),c=document.querySelector('.modal-content'),a=document.querySelector('.lubi-modal-actions'),r=m.getBoundingClientRect();const controls=[...c.querySelectorAll('input,select,textarea,button')].filter(e=>e.offsetParent!==null);const out={overflow:document.documentElement.scrollWidth-innerWidth,contained:controls.every(e=>{const b=e.getBoundingClientRect();return b.left>=r.left-1&&b.right<=r.right+1}),actionsVisible:a.getBoundingClientRect().bottom<=innerHeight+1&&a.getBoundingClientRect().top>=0,hasMore:!!c.querySelector('.lubi-light-more'),actualInputs:c.querySelectorAll('[data-actual]').length};parent.postMessage('LIGHT:'+encodeURIComponent(JSON.stringify(out)),'*')});<\/script>`;
  const esc=s=>s.replace(/&/g,'&amp;').replace(/"/g,'&quot;').replace(/</g,'&lt;').replace(/>/g,'&gt;');
  const source=`<!doctype html><html><head><meta charset=utf-8><style>${shim}${styles}</style></head><body class="theme-${theme}">${fragment}${probe}</body></html>`;
  const wrapper=`<!doctype html><meta charset=utf-8><style>body{margin:0}iframe{border:0;width:${w}px;height:${h}px}</style><script>addEventListener('message',e=>{if(typeof e.data==='string'&&e.data.startsWith('LIGHT:')){const p=document.createElement('pre');p.textContent=e.data;document.body.append(p)}})</script><iframe srcdoc="${esc(source)}"></iframe>`;
  const file=join(tmp,`${theme}-${w}.html`);writePage(file,wrapper);
  const res=spawnSync(browser,['--headless=new','--disable-gpu','--no-first-run',`--window-size=${w+40},${h+40}`,'--virtual-time-budget=2000',`--user-data-dir=${join(tmp,theme+w)}`,'--dump-dom',pathToFileURL(file).href],{encoding:'utf8',timeout:45000,maxBuffer:10*1024*1024});
  assert.equal(res.status,0,res.stderr);const found=[...res.stdout.matchAll(/LIGHT:(%7B[^<\s]+)/g)].at(-1);assert(found,'missing metrics');const m=JSON.parse(decodeURIComponent(found[1]));assert(m.overflow<=1&&m.contained&&m.actionsVisible&&m.hasMore&&m.actualInputs===0,JSON.stringify(m));console.log(`PASS light task browser ${theme} ${w}x${h}`);
 }
}finally{rmSync(tmp,{recursive:true,force:true})}
